function array = stackPositiveAndNegativeFields(points, fieldTagPos, fieldTagNeg)
% stackPositiveAndNegativeFields: Concatenate positive and negative point fields.
%
%   Inputs:
%       points: The input structure generated by UniformRectPrimitiveUniformRooftops class.
%       fieldTagPos: Name of the struct field containing positive rooftop points.
%       fieldTagNeg: Name of the struct field containing negative rooftop points.
%
%   Output:
%       array: 3×N×2 numeric array, where:
%              array(:,:,1) contains all positive points,
%              array(:,:,2) contains all negative points.

    array = cat(3, points.(fieldTagPos), points.(fieldTagNeg));
end
